 {"chain_small",32,0},{"chain_boundary",256,0},{"chain_above_boundary",257,0},{"chain_large",300000,0},
 {"star_small",64,0},{"star_boundary",256,0},{"star_above_boundary",257,0},{"star_large",300000,0},
 {"grid_small",64,8},{"grid_medium",4096,64},{"grid_large",199809,447},
