 {"improve_small",64,16},{"improve_medium",4096,16},{"improve_large",50000,8},
 {"hub_small",64,0},{"hub_large",300000,0},
 {"fork_chain_large",300000,0},{"chain_fork_large",300000,0},{"forced_cycle_large",300000,0}
