static std::uint64_t rng_state;
static std::uint64_t random_value() {
 auto z=(rng_state+=0x9e3779b97f4a7c15ULL); z=(z^(z>>30))*0xbf58476d1ce4e5b9ULL;
 z=(z^(z>>27))*0x94d049bb133111ebULL; return z^(z>>31);
}
static WGraph make_graph(const BenchCase& c) {
 rng_state=0xa8500c11999ULL; WGraph g(c.n);
 const auto add=[&](int u,int v,std::int64_t w){g[u].emplace_back(v,w);};
 if(c.name=="fork_chain_large" || c.name=="chain_fork_large" || c.name=="forced_cycle_large") {
  const int dead=c.n-2;
  std::vector<int> order;
  for(int i=0;i<c.n-1;++i) if(i!=dead) order.push_back(i);
  for(std::size_t i=order.size();i>2;--i) std::swap(order[i-1],order[1+random_value()%(i-1)]);
  order.push_back(c.n-1);
  for(std::size_t i=1;i<order.size();++i)add(order[i-1],order[i],1);
  if(c.name=="fork_chain_large")add(0,dead,0);
  else if(c.name=="chain_fork_large")add(order[order.size()/2],dead,0);
  else add(order.back(),0,0);
 }
 else if(c.name.starts_with("chain")) for(int i=1;i<c.n;++i) add(i-1,i,1);
 else if(c.name.starts_with("star")) for(int i=1;i<c.n;++i) add(0,i,(std::int64_t{i}*998244353)%1000000001);
 else if(c.name.starts_with("grid")) {
  for(int i=0;i<c.n;++i) {if(i%c.parameter+1<c.parameter)add(i,i+1,random_value()%1000000001);
   if(i+c.parameter<c.n)add(i,i+c.parameter,random_value()%1000000001);}
 } else if(c.name.starts_with("reach")) for(int i=1;i<c.parameter;++i)add(i-1,i,1);
 else if(c.name.starts_with("improve")) {
  for(int v=1;v<c.n;++v)for(int d=c.parameter;d>=1;--d)add(0,v,std::int64_t{d}*1000000+v);
 } else if(c.name.starts_with("hub")) {
  for(int i=1;i<c.n;++i)add(0,i,1000000000-i);
  for(int i=1;i<c.n-1;++i)add(c.n-1,i,i);
 } else {
  const auto weight=[&]() -> std::int64_t {
   if(c.name.starts_with("zero_one")) return random_value()&1;
   if(c.name.starts_with("zero")) return 0;
   if(c.name.starts_with("large_weight"))return 1000000000-random_value()%32;
   return random_value()%1000000001;
  };
  for(int i=1;i<c.n;++i)add(i-1,i,weight());
  for(int u=0;u<c.n;++u)for(int j=0;j<c.parameter;++j)add(u,random_value()%c.n,weight());
 }
 return g;
}
static std::uint64_t checksum(const std::vector<std::int64_t>& d,const std::vector<int>& p) {
 std::uint64_t sum=0x5434543; for(auto x:d)sum=sum*1000003+static_cast<std::uint64_t>(x);
 for(auto x:p)sum=sum*1000033+x;
 return sum;
}


