 h.reset_for_test();for(std::size_t i=0;i<keys.size();++i)h.emplace(keys[i],static_cast<int>(i));
 std::uint64_t sum=0;while(!h.empty()){auto[k,v]=h.pop<V>();sum+=k*113+v;}return sum;
}
int main(int argc,char**argv){
