 using Fn=std::uint64_t(*)(DijkstraRadixHeap&,const std::vector<std::uint64_t>&);Fn f[]={run<0>,run<1>,run<2>};
 auto ref=run<0>(h,keys);for(int r=-3;r<31;++r)for(int k=0;k<3;++k){int v=(k+r+3)%3;auto cpu=cpu_now();auto begin=std::chrono::steady_clock::now();auto sum=f[v](h,keys);double wall=std::chrono::duration<double,std::nano>(std::chrono::steady_clock::now()-begin).count();cpu=cpu_now()-cpu;if(sum!=ref)return 2;if(r>=0)std::printf("{\"shape\":\"%s\",\"variant\":%d,\"round\":%d,\"wall_ns\":%.3f,\"cpu_ns\":%.3f,\"checksum\":%ju}\n",shape.c_str(),v,r,wall,cpu,static_cast<std::uintmax_t>(sum));}
}

