  auto pop=[&]{auto got=singleton?heap.pop_singleton():heap.pop();if(ref.empty()||got.first!=ref.begin()->first)throw std::runtime_error("minimum");auto it=ref.find(got);if(it==ref.end())throw std::runtime_error("identity");last=got.first;ref.erase(it);++checks;};
